import React, { useState } from "react";
import { Box, Typography, TextField, Button, Chip, Grid, Select, MenuItem, FormControl, InputLabel, Dialog, DialogTitle, DialogContent, DialogActions } from "@mui/material";
import { ZB_COLORS } from "./theme";

const categories = ["All", "Career", "Finance", "Law", "Technology", "Marketing", "Procurement", "Business", "Other"];

const defaultResources = [
  { title: "Introduction to Information Technology", link: "https://www.open.edu/openlearn/science-maths-technology/introduction-information-technology/content-section-0", category: "Technology", featured: true, tags: ["IT", "basics"], description: "Free Open University course covering IT fundamentals.", type: "Course" },
  { title: "Digital Marketing Basics", link: "https://www.coursera.org/learn/digital-marketing-basics", category: "Marketing", featured: false, tags: ["marketing", "digital"], description: "Beginner's course on digital marketing concepts.", type: "Course" },
  { title: "Procurement and Supply Chain Management", link: "https://www.open.edu/openlearn/money-business/procurement-and-supply-chain-management/content-section-0", category: "Procurement", featured: false, tags: ["procurement", "supply chain"], description: "Learn the essentials of procurement and supply chain.", type: "Course" },
  { title: "Business Communication Essentials", link: "https://www.saylor.org/courses/bus210/", category: "Business", featured: false, tags: ["business", "communication"], description: "Free course on effective business communication.", type: "Course" },
  { title: "Personal Finance 101", link: "https://www.khanacademy.org/college-careers-more/personal-finance", category: "Finance", featured: true, tags: ["finance", "personal finance"], description: "Khan Academy's comprehensive personal finance course.", type: "Course" },
  { title: "Introduction to Business Law", link: "https://www.open.edu/openlearn/money-business/introduction-business-law/content-section-0", category: "Law", featured: false, tags: ["law", "business law"], description: "Free Open University course on business law.", type: "Course" },
  { title: "Entrepreneurship: Launching an Innovative Business", link: "https://www.coursera.org/learn/wharton-entrepreneurship", category: "Business", featured: true, tags: ["entrepreneurship", "innovation"], description: "Wharton's free course on launching a business.", type: "Course" },
  { title: "Financial Literacy for Youth (OpenStax)", link: "https://openstax.org/details/books/personal-finance", category: "Finance", featured: false, tags: ["finance", "youth"], description: "Open-access textbook on personal finance.", type: "Book" },
  { title: "Supply Chain Fundamentals", link: "https://www.edx.org/course/supply-chain-fundamentals", category: "Procurement", featured: false, tags: ["supply chain", "basics"], description: "Fundamentals of supply chain management.", type: "Course" },
  { title: "Marketing in a Digital World", link: "https://www.coursera.org/learn/marketing-digital", category: "Marketing", featured: false, tags: ["marketing", "strategy"], description: "Digital marketing strategies for the modern world.", type: "Course" },
];

const typeColor = { Course: "#2196f3", Book: "#4caf50", Video: "#ff9800", Article: "#9c27b0" };

export default function Library() {
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");
  const [openResource, setOpenResource] = useState(null);
  const [suggestTitle, setSuggestTitle] = useState("");
  const [suggestLink, setSuggestLink] = useState("");
  const [suggestCat, setSuggestCat] = useState("");
  const [suggested, setSuggested] = useState(false);

  const featured = defaultResources.filter(r => r.featured);
  const filtered = defaultResources.filter(r =>
    (category === "All" || r.category === category) &&
    (!search || r.title.toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <Box sx={{ maxWidth: 1100, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Resources</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>Library</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>Curated free courses, books, and tools to grow your career.</Typography>

      {/* Featured */}
      {featured.length > 0 && (
        <Box sx={{ mb: 4 }}>
          <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: ZB_COLORS.gold, mb: 2, fontSize: "0.9rem" }}>⭐ Featured</Typography>
          <Grid container spacing={2}>
            {featured.map((r, i) => (
              <Grid item xs={12} sm={6} md={4} key={i}>
                <Box sx={{ background: "rgba(255,214,0,0.06)", border: `0.5px solid rgba(255,214,0,0.2)`, borderRadius: "12px", p: 2.5, cursor: "pointer", "&:hover": { background: "rgba(255,214,0,0.1)" } }} onClick={() => setOpenResource(r)}>
                  <Box sx={{ display: "flex", gap: 1, mb: 1 }}>
                    <Chip label={r.category} size="small" sx={{ background: "rgba(255,255,255,0.07)", color: "rgba(255,255,255,0.7)", fontFamily: "DM Sans", fontSize: "0.7rem" }} />
                    <Chip label={r.type} size="small" sx={{ background: `${typeColor[r.type] || "#999"}20`, color: typeColor[r.type] || "#999", fontFamily: "DM Sans", fontSize: "0.7rem" }} />
                  </Box>
                  <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.9rem", mb: 0.75 }}>{r.title}</Typography>
                  <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{r.description}</Typography>
                </Box>
              </Grid>
            ))}
          </Grid>
        </Box>
      )}

      {/* Filters */}
      <Box sx={{ display: "flex", gap: 2, mb: 3, flexWrap: "wrap", alignItems: "center" }}>
        <TextField
          placeholder="Search resources…"
          size="small"
          value={search}
          onChange={e => setSearch(e.target.value)}
          sx={{ minWidth: 220 }}
        />
        <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}>
          {categories.map(cat => (
            <Chip
              key={cat} label={cat} onClick={() => setCategory(cat)} size="small"
              sx={{
                cursor: "pointer",
                background: category === cat ? "rgba(255,214,0,0.15)" : "rgba(255,255,255,0.05)",
                border: `0.5px solid ${category === cat ? ZB_COLORS.gold : ZB_COLORS.border}`,
                color: category === cat ? ZB_COLORS.gold : "rgba(255,255,255,0.65)",
                fontFamily: "DM Sans",
              }}
            />
          ))}
        </Box>
      </Box>

      {/* Resource grid */}
      <Grid container spacing={2} sx={{ mb: 5 }}>
        {filtered.map((r, i) => (
          <Grid item xs={12} sm={6} md={4} key={i}>
            <Box
              sx={{ background: ZB_COLORS.cardBg, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 2.5, cursor: "pointer", height: "100%", display: "flex", flexDirection: "column", transition: "all 0.2s", "&:hover": { background: ZB_COLORS.cardHover, borderColor: "rgba(255,255,255,0.15)", transform: "translateY(-2px)" } }}
              onClick={() => setOpenResource(r)}
            >
              <Box sx={{ display: "flex", gap: 1, mb: 1 }}>
                <Chip label={r.category} size="small" sx={{ background: "rgba(255,255,255,0.07)", color: "rgba(255,255,255,0.7)", fontFamily: "DM Sans", fontSize: "0.7rem" }} />
                <Chip label={r.type} size="small" sx={{ background: `${typeColor[r.type] || "#999"}20`, color: typeColor[r.type] || "#999", fontFamily: "DM Sans", fontSize: "0.7rem" }} />
              </Box>
              <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "0.875rem", mb: 0.75, flexGrow: 1 }}>{r.title}</Typography>
              <Typography sx={{ fontSize: "0.78rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{r.description}</Typography>
            </Box>
          </Grid>
        ))}
      </Grid>

      {/* Suggest */}
      <Box sx={{ background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 3 }}>
        <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 2 }}>Suggest a resource</Typography>
        {suggested ? (
          <Typography sx={{ color: "#4caf50", fontFamily: "DM Sans" }}>✓ Thanks! Your suggestion will be reviewed.</Typography>
        ) : (
          <Grid container spacing={2}>
            <Grid item xs={12} sm={4}><TextField label="Title" fullWidth size="small" value={suggestTitle} onChange={e => setSuggestTitle(e.target.value)} /></Grid>
            <Grid item xs={12} sm={4}><TextField label="Link" fullWidth size="small" value={suggestLink} onChange={e => setSuggestLink(e.target.value)} /></Grid>
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth size="small">
                <InputLabel>Category</InputLabel>
                <Select value={suggestCat} label="Category" onChange={e => setSuggestCat(e.target.value)}>
                  {categories.filter(c => c !== "All").map(c => <MenuItem key={c} value={c}>{c}</MenuItem>)}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <Button variant="contained" onClick={() => setSuggested(true)} disabled={!suggestTitle || !suggestLink || !suggestCat}>Submit suggestion</Button>
            </Grid>
          </Grid>
        )}
      </Box>

      {/* Detail dialog */}
      <Dialog open={!!openResource} onClose={() => setOpenResource(null)} maxWidth="sm" fullWidth PaperProps={{ sx: { background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}` } }}>
        <DialogTitle sx={{ color: "#fff", fontFamily: "Sora" }}>{openResource?.title}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: "flex", gap: 1, mb: 2 }}>
            <Chip label={openResource?.category} size="small" sx={{ background: "rgba(255,255,255,0.07)", color: "rgba(255,255,255,0.7)", fontFamily: "DM Sans" }} />
            {openResource?.type && <Chip label={openResource.type} size="small" sx={{ background: `${typeColor[openResource.type] || "#999"}20`, color: typeColor[openResource.type] || "#999", fontFamily: "DM Sans" }} />}
          </Box>
          <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 3 }}>{openResource?.description}</Typography>
          <Button href={openResource?.link} target="_blank" rel="noopener noreferrer" variant="contained">Open resource →</Button>
        </DialogContent>
        <DialogActions><Button onClick={() => setOpenResource(null)} sx={{ color: ZB_COLORS.textMuted }}>Close</Button></DialogActions>
      </Dialog>
    </Box>
  );
}
